// Central config. RPC_URL is the switch: local anvil (default) or Robinhood testnet 46630.
import { fileURLToPath } from "node:url";
import path from "node:path";

export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const REPO = path.resolve(ROOT, "..");
export const TESTNET_CHAIN_ID = 46630;
export const MAINNET_CHAIN_ID = 4663;  // chain-guard: allow (used only to refuse mainnet)

// Load server/.env.demo (generated by `npm run demo:env`, gitignored, chmod 600) without overriding real env.
import fsx from "node:fs";
{
  const f = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", ".env.demo");
  if (fsx.existsSync(f) && process.env.STOCKCLAW_NO_ENV_FILE !== "1")
    for (const line of fsx.readFileSync(f, "utf8").split("\n")) { const m = line.match(/^\s*([A-Z0-9_]+)=(.*)$/); if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2].trim(); }
}
export const RPC_URL = process.env.RPC_URL ?? "http://127.0.0.1:8545";
/** SC-1: parse with new URL(); hostname must be exactly 127.0.0.1, localhost or ::1; no userinfo. */
export function isLocalRpc(url: string): boolean {
  let u: URL; try { u = new URL(url); } catch { return false; }
  if (!["http:", "https:", "ws:", "wss:"].includes(u.protocol)) return false;
  if (u.username || u.password) return false;
  return ["127.0.0.1", "localhost", "[::1]", "::1"].includes(u.hostname.toLowerCase());
}
/** Hostname check only (SC-1). On its own this is NOT proof of a local chain: a localhost tunnel or proxy can point at
 * public 46630 (same chain id). Local-only relaxations must use isLocalChain() (R7-3). */
export const IS_LOCAL = isLocalRpc(RPC_URL);
// R7-3: local = localhost RPC hostname AND a node verified to really be anvil (web3_clientVersion ~ /anvil/ and
// anvil_nodeInfo answers). Set by chain.assertChain() at startup; unverified => false (fail closed).
let anvilVerified: boolean | null = null, nodeClient = "";
export const setLocalNode = (anvil: boolean, client: string) => { anvilVerified = anvil; nodeClient = client; };
export const isLocalChain = () => IS_LOCAL && anvilVerified === true;
export const localNodeInfo = () => ({ hostnameLocal: IS_LOCAL, anvilVerified, client: nodeClient });
export const PORT = Number(process.env.PORT ?? 8787);
/** R7-6: bind loopback by default (venue Wi-Fi can't reach the API/MCP). HOST overrides it, with a loud warning when
 * it isn't loopback. */
export const isLoopbackHost = (h: string) => ["127.0.0.1", "localhost", "::1", "[::1]"].includes(h.trim().toLowerCase()) || /^127\.\d+\.\d+\.\d+$/.test(h.trim());
export function listenHost(env = process.env): { host: string; warning: string | null } {
  const host = (env.HOST ?? "").trim() || "127.0.0.1";
  return { host, warning: isLoopbackHost(host) ? null : `HOST=${host} is not loopback: the API, MCP and owner dashboard are reachable from the network (bearer tokens only). Use this only behind a reverse proxy / access control.` };
}
/** R7-6: client-supplied headers (CF-IPCountry geo, X-Forwarded-For) are only trusted when TRUSTED_PROXY is set:
 * "1"/"true" = a proxy on loopback (e.g. cloudflared), otherwise an Express "trust proxy" value (IPs / CIDRs / hop count). */
export function trustedProxy(env = process.env): string | number | null {
  const v = (env.TRUSTED_PROXY ?? "").trim();
  if (!v || v === "0" || v.toLowerCase() === "false") return null;
  if (v === "1" || v.toLowerCase() === "true") return "loopback";
  return /^\d+$/.test(v) ? Number(v) : v;
}
export const DATA_DIR = process.env.DATA_DIR ?? path.join(ROOT, "data");
export const DEPLOYMENTS_FILE = process.env.DEPLOYMENTS_FILE ?? path.join(DATA_DIR, IS_LOCAL ? "local-46630.json" : "testnet-46630.json");
// Block explorer (Blockscout). Testnet 46630: explorer.testnet.chain.robinhood.com. Local anvil: none (hash shown as text).
export const EXPLORER: string | null = IS_LOCAL ? null : (process.env.EXPLORER_URL ?? "https://explorer.testnet.chain.robinhood.com").replace(/\/+$/, "");
export const explorerTx = (hash: string) => (EXPLORER && hash ? `${EXPLORER}/tx/${hash}` : null);
export const explorerAddress = (addr: string) => (EXPLORER && addr ? `${EXPLORER}/address/${addr}` : null);
export const KEEPER_INTERVAL_MS = Number(process.env.KEEPER_INTERVAL_MS ?? 60_000);
/** "open" forces market open (local demo only); "schedule" uses the onchain NYSE schedule (halts off-hours). */
export const getMarketMode = () => (process.env.MARKET_MODE ?? (isLocalChain() ? "open" : "schedule")) as "open" | "schedule";
// Review S-1: separate tokens. Owner token = dashboard/owner actions; MCP token = agent. Read at call time.
export const ownerToken = () => process.env.OWNER_API_TOKEN;
export const mcpToken = () => process.env.MCP_API_TOKEN;
/** R3-1: both tokens required on EVERY chain. Escape hatch: ALLOW_OPEN_LOCAL=1, local chain only, loud warning. */
export function assertTokensConfigured() {
  if (!ownerToken() || !mcpToken()) {
    if (process.env.ALLOW_OPEN_LOCAL === "1" && !isLocalChain()) throw new Error(`REFUSING to start: ALLOW_OPEN_LOCAL=1 needs a verified local anvil node (RPC hostname local=${IS_LOCAL}, anvil verified=${anvilVerified}). Set OWNER_API_TOKEN and MCP_API_TOKEN.`);
    if (process.env.ALLOW_OPEN_LOCAL === "1" && isLocalChain()) {
      console.warn("\n" + "!".repeat(78) + "\n!! WARNING: ALLOW_OPEN_LOCAL=1 -> owner and MCP endpoints are OPEN (no tokens). LOCAL DEV ONLY.\n!! Never use this for the demo. Run `npm run demo:env` and restart.\n" + "!".repeat(78) + "\n");
      return;
    }
    throw new Error("REFUSING to start: OWNER_API_TOKEN and MCP_API_TOKEN must both be set (run `npm run demo:env`). ALLOW_OPEN_LOCAL=1 is allowed on a local chain only.");
  }
  if (ownerToken() && ownerToken() === mcpToken()) throw new Error("OWNER_API_TOKEN and MCP_API_TOKEN must differ");
}

